export function characterFromImport(rec) {
  const height = rec.height ?? 132;
  return {
    id: rec.id,
    name: rec.name,
    element: rec.element,
    symbol: rec.symbol,
    atomicNumber: rec.atomicNumber,
    tagline: rec.tagline ?? '',
    teach: rec.teach ?? '',
    art: {
      key: rec.art.key,
      file: rec.art.file,
      facing: rec.art.facing ?? 1,
      height,
      bodyW: rec.bodyW ?? Math.round(height * 0.34),
      bodyH: rec.bodyH ?? Math.round(height * 0.88),
      use3d: true,
      sheets: rec.art.sheets,
    },
    stats: {
      speed: 300,
      jumpVelocity: 640,
      airJumps: rec.airJumps ?? 1,
      weight: 1,
      gravityScale: 1,
    },
    defense: { heat: 0, physical: 0, electrical: 0, chemical: 0 },
    palettes: rec.palettes,
    body: rec.body ?? {
      headRadius: 20, torsoWidth: 38, torsoHeight: 44,
      armLength: 28, armWidth: 11, legLength: 28, legWidth: 12, antenna: false,
    },
    moves: {
      basicCharge: { name: 'Charge', type: 'kinetic', damage: 6, duration: 240, cooldown: 500, baseKnockback: 160, knockbackGrowth: 5 },
      basicDirectional: { name: 'Strike', type: 'kinetic', damage: 6, duration: 220, cooldown: 400, rangeW: 70, rangeH: 46, baseKnockback: 160, knockbackGrowth: 5 },
      specialDefense: { name: 'Guard', kind: 'block', blockReduction: 0.5, duration: 500, cooldown: 500, baseKnockback: 0, knockbackGrowth: 0 },
      specialDirectional: { name: 'Burst', kind: 'burst', type: 'kinetic', damage: 8, radius: 70, duration: 260, cooldown: 600, baseKnockback: 180, knockbackGrowth: 5 },
    },
  };
}
